//../../assets/images/svg/user-role-bg.png\");\n    background-color: #1d4e4d;\n    background-repeat: no-repeat;\n    background-size: cover;\n    background-position: center;\n    border-radius: 10px;\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-end;\n    padding: 0 1.5rem;\n    color: #ffffff;\n\n    background-blend-mode: multiply;\n    mix-blend-mode: multiply;\n    backdrop-filter: opacity(.4);\n}\n\n.banner__text-primary {\n    font-size: 36px;\n}\n\n.btn-orange-two {\n    background: #04aed4;\n    border-radius: 5px;\n    height: 44px;\n    font-family: Nunito;\n    font-style: normal;\n    font-weight: 600;\n    font-size: 15px;\n    line-height: 20px;\n    color: #ffffff;\n}\n\n\n/* ==================== Search ==================== */\n\n.search {\n    display: flex;\n    align-items: center;\n    margin-top: 5rem;\n}\n\n.nav-pills .nav-link.active,\n.nav-pills .show>.nav-link {\n    color: #0A1128;\n    font-weight: 600;\n    background: #FBF2EB;\n    border-bottom: 2px solid #04aed4;\n    ;\n    font-weight: 600;\n    border-radius: 0;\n    padding: 8px 35px;\n}\n\n.nav-pills .nav-link,\n.nav-pills .show>.nav-link {\n    color: #0a1128;\n    /* opacity: 0.6; */\n}\n\n\n\n.has-search .form-control {\n    padding-left: 2.375rem;\n}\n\n.has-search .form-control-feedback {\n    position: absolute;\n    z-index: 2;\n    display: block;\n    width: 2.375rem;\n    height: 2.375rem;\n    line-height: 2.375rem;\n    text-align: center;\n    pointer-events: none;\n    color: #aaa;\n}\n\n\n\n\n\n/* ================= table ====================== */\ntable.client-table {\n    border-collapse: separate;\n    border-spacing: 0 1em;\n}\n\n.list .table thead {\n    color: #4c75bd;\n}\n\n.list .table thead tr th {\n    font-weight: 600;\n}\n\n.list .table thead .head {\n    /* display: flex;\n      align-items: center;\n      color: #0a1128;\n      font-weight: 600; */\n    padding-left: 3.5rem;\n}\n\n.list .table tbody .user {\n    display: flex;\n    align-items: center;\n    color: #0a1128;\n    font-weight: 600;\n    padding-left: 1.5rem;\n    padding-left: 3.5rem;\n    position: relative;\n    opacity: none;\n}\n\n.list .table tbody .user span {\n    position: absolute;\n    bottom: 20px;\n    left: 15px;\n}\n\n.list .table tbody .user div p,\nh6 {\n    margin-bottom: .1rem;\n}\n\n.list .table tbody .user div h6 {\n    color: #355691;\n    font-size: 14px;\n}\n\n.list .table tbody .user div p {\n    color: #0a1128;\n    opacity: 0.6;\n    font-size: 14px;\n}\n\n.list .table tbody tr {\n    background: #ffffff;\n    box-shadow: 10px 10px 30px rgba(211, 220, 231, 0.4);\n    border-radius: 5px;\n}\n\n.list .table tbody td:not(:first-child) {\n    color: #0a1128;\n    opacity: 0.6;\n}\n\n.list .table tbody .status_active {\n    background: #ebfffa;\n    border-radius: 10px;\n    color: #09b78a;\n    font-weight: 600;\n    width: 110px;\n    height: 26px;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    padding: 17px 40px;\n}\n\n.list .table tbody .status_inactive {\n    background: #fae5e7;\n    border-radius: 10px;\n    color: #d72638;\n    font-weight: 600;\n    width: 110px;\n    height: 26px;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    padding: 17px 40px;\n}\n\n.btn-link {\n    color: #014d94;\n    opacity: 0.6;\n    text-decoration: underline;\n    font-weight: bold;\n    font-size: 14px;\n    padding: 0;\n}\n\n#pills-profile .user,\n#pills-profile .action {\n    color: #355691;\n\n\n}\n\n#pills-profile .action {\n\n    color: #355691;\n    opacity: inherit;\n\n}\n\n#pill-profile table tr,\ntd {\n    padding: 20px;\n}\n\n/* sms modal  */\n.modal-content {\n    border-radius: 0 !important;\n    border: none;\n    position: relative;\n\n}\n\n\n.modal-head {\n    padding: 20px 40px;\n    background: #EBF0F5;\n    /* display: flex;\n    justify-content: space-between; */\n}\n\n\n\n.client-modal {\n    display: flex;\n    flex-direction: column;\n\n    padding: 0px 40px;\n\n}\n\nform {\n    width: 100%;\n}\n\n\n\ntextarea {\n    height: 150px;\n}\n\n.close {\n    cursor: pointer;\n}\n\nh6 {\n    font-weight: bold;\n    font-weight: 600;\n}\n\n/* .form-group .custom-control-label::before {\n\n    background: #09B78A;\n    font-size: 16px;\n}\n\n.form-group .custom-control-label::after {\n\n    background: #ffffff;\n} */\n\n\n\n\n.class-label {\n    margin-right: 5rem;\n}\n\n.fa-tasks {\n        color: firebrick;\n}\n    \n\n    \n        \n        \n            \n                Legend\n            \n            \n                Html element\n            \n            \n                Component\n            \n            \n                Html element with directive\n            \n        \n    \n\n    \n\n\n\n\n\n\n        var COMPONENT_TEMPLATE = '             Accounts        Showing all roles and permissions          New Role    -->             Accounts        Showing all Roles and Permssion          New Roles                                 Users         -->                  Roles                                                                                                                Full Name                                 Email                 Role                 Date Added                                 Status                                                                                                                               Chukwudi Okoli                                                   PRT/2016/001                Parent                Parent                Active                                                   -->                                    You have not added any Role                           0\">                                                    Role Title                                Role ID                 No. of Active Users                 Date Created                                                                                                                       {{role?.name}}                                {{role.id}}                {{role?.usersCount}}                17/03/2020                                                    Assign User                    Edit Role                    Delete Role                                                                                       Assign Role to a user                                                            Users *                                                         Roles *                                                         Cancel                         Assign Role                              '\n    var COMPONENTS = [{'name': 'AboutComponent', 'selector': 'app-about'},{'name': 'AccountMappingComponent', 'selector': 'app-account-mapping'},{'name': 'AccountPanelComponent', 'selector': 'app-account-panel'},{'name': 'AccountSettingsComponent', 'selector': 'app-account-settings'},{'name': 'AddStudentsComponent', 'selector': 'app-add-students'},{'name': 'AdminAlumniCreateEventComponent', 'selector': 'app-admin-alumni-create-event'},{'name': 'AdminAlumniEventsComponent', 'selector': 'app-admin-alumni-events'},{'name': 'AdminAlumniListComponent', 'selector': 'app-admin-alumni-list'},{'name': 'AdminLoginComponent', 'selector': 'app-admin-login'},{'name': 'AlumniAlumniComponent', 'selector': 'app-alumni-alumni'},{'name': 'AlumniComponent', 'selector': 'app-alumni'},{'name': 'AlumniEventDetailComponent', 'selector': 'app-alumni-event-detail'},{'name': 'AlumniEventsComponent', 'selector': 'app-alumni-events'},{'name': 'AlumniHomeComponent', 'selector': 'app-alumni-home'},{'name': 'AlumniProfileComponent', 'selector': 'app-alumni-profile'},{'name': 'AlumniRecordsComponent', 'selector': 'app-alumni-records'},{'name': 'AlumniTranscriptComponent', 'selector': 'app-alumni-transcript'},{'name': 'AppComponent', 'selector': 'app-root'},{'name': 'AssignmentComponent', 'selector': 'app-assignment'},{'name': 'AssignmentComponent', 'selector': 'app-assign