      url: "modules/AddStudentsModule.html",
      title: "module - AddStudentsModule",
      body: "\n                   \n\n\n\n\n    Modules\n    AddStudentsModule\n\n\n\n    \n        \n\n\n\n\n\ndependencies\n\ndependencies\n\ncluster_AddStudentsModule\n\n\n\ncluster_AddStudentsModule_declarations\n\n\n\ncluster_AddStudentsModule_imports\n\n\n\n\nAddStudentsComponent\n\nAddStudentsComponent\n\n\n\nAddStudentsModule\n\nAddStudentsModule\n\nAddStudentsModule -->\n\nAddStudentsComponent->AddStudentsModule\n\n\n\n\n\nBasicDetailsComponent\n\nBasicDetailsComponent\n\nAddStudentsModule -->\n\nBasicDetailsComponent->AddStudentsModule\n\n\n\n\n\nContactDetailsComponent\n\nContactDetailsComponent\n\nAddStudentsModule -->\n\nContactDetailsComponent->AddStudentsModule\n\n\n\n\n\nImagesComponent\n\nImagesComponent\n\nAddStudentsModule -->\n\nImagesComponent->AddStudentsModule\n\n\n\n\n\nMedicalDetailsComponent\n\nMedicalDetailsComponent\n\nAddStudentsModule -->\n\nMedicalDetailsComponent->AddStudentsModule\n\n\n\n\n\nSocialDetailsComponent\n\nSocialDetailsComponent\n\nAddStudentsModule -->\n\nSocialDetailsComponent->AddStudentsModule\n\n\n\n\n\nAddStudentsRoutingModule\n\nAddStudentsRoutingModule\n\nAddStudentsModule -->\n\nAddStudentsRoutingModule->AddStudentsModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/school/add-students/add-students.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Declarations\n                    \n                        \n                            AddStudentsComponent\n                        \n                        \n                            BasicDetailsComponent\n                        \n                        \n                            ContactDetailsComponent\n                        \n                        \n                            ImagesComponent\n                        \n                        \n                            MedicalDetailsComponent\n                        \n                        \n                            SocialDetailsComponent\n                        \n                    \n                \n                \n                    Imports\n                    \n                        \n                            AddStudentsRoutingModule\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { CommonModule } from '@angular/common';\n\nimport { AddStudentsRoutingModule } from './add-students-routing.module';\nimport { AddStudentsComponent } from './add-students.component';\nimport { BasicDetailsComponent } from './basic-details/basic-details.component';\nimport { SocialDetailsComponent } from './social-details/social-details.component';\nimport { ContactDetailsComponent } from './contact-details/contact-details.component';\nimport { MedicalDetailsComponent } from './medical-details/medical-details.component';\nimport { FormsModule, ReactiveFormsModule } from '@angular/forms';\nimport { ImagesComponent } from './images/images.component';\nimport { NgMultiSelectDropDownModule } from 'ng-multiselect-dropdown';\n\n\n@NgModule({\n  declarations: [\n    AddStudentsComponent, BasicDetailsComponent, SocialDetailsComponent, ContactDetailsComponent, MedicalDetailsComponent, ImagesComponent],\n  imports: [\n    CommonModule,\n    ReactiveFormsModule,\n    NgMultiSelectDropDownModule,\n    FormsModule,\n    AddStudentsRoutingModule\n  ]\n})\nexport class AddStudentsModule { }\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
