      url: "modules/FinanceModule.html",
      title: "module - FinanceModule",
      body: "\n                   \n\n\n\n\n    Modules\n    FinanceModule\n\n\n\n    \n        \n\n\n\n\n\ndependencies\n\ndependencies\n\ncluster_FinanceModule\n\n\n\ncluster_FinanceModule_imports\n\n\n\n\nFinanceRoutingModule\n\nFinanceRoutingModule\n\n\n\nFinanceModule\n\nFinanceModule\n\nFinanceModule -->\n\nFinanceRoutingModule->FinanceModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/school/finance/finance.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Imports\n                    \n                        \n                            FinanceRoutingModule\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { CommonModule } from '@angular/common';\n\nimport { FinanceRoutingModule } from './finance-routing.module';\nimport { BillingComponent } from './billing/billing.component';\nimport { FormsModule, ReactiveFormsModule } from '@angular/forms';\n\nimport { NgxPaginationModule } from 'ngx-pagination';\n\n\n\n@NgModule({\n  declarations: [BillingComponent],\n  imports: [\n    CommonModule,\n    ReactiveFormsModule,\n    FormsModule,\n    NgxPaginationModule,\n    FinanceRoutingModule\n  ]\n})\nexport class FinanceModule { }\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
