    // alert(this.notification);\n        this.notification = res\n      }\n    )\n  }\n \n  dismiss(){\n    this.notify.dismissMessage()\n  }\n\n}\n\n    \n\n    \n        \n  \n    \n    \n    {{notification.content}} \n     -->\n    \n    \n\n  \n\n\n    \n\n    \n                \n                    ./notifications.component.css\n                \n                .notification {\n  position: fixed;\n  left: 35vw;\n  margin: 0 auto;\n  top: 8vh;\n  width: 40vw;\n  z-index: 34444444444444444444444;\n}\n\n.alert-info {\n  background: #ddf8e9;\n  border: 2px solid #a9edc8;\n  box-sizing: border-box;\n  border-radius: 5px;\n  font-family: Nunito;\n  font-style: normal;\n  font-size: 20px;\n  line-height: 25px;\n  color: #1c9d52;\n  font-weight: 600;\n}\n\n.alert-danger {\n  background: #FFE5E5;\n  border: 2px solid #FEC5C5;\n  box-sizing: border-box;\n  border-radius: 5px;\n  font-family: Nunito;\n  font-style: normal;\n  font-size: 20px;\n  line-height: 25px;\n  color: #CE4346;\n  font-weight: 600;\n}\n.alert-success {\n  background: #eafbf1;\n  /* border: 2px solid #28a745 ; */\n  border: 2px solid #a9edc8;\n\n  box-sizing: border-box;\n  border-radius: 5px;\n  font-family: Nunito;\n  font-style: normal;\n  /* font-weight: 600; */\n  font-size: 20px;\n  line-height: 25px;\n  color: #1C9D52;\n  font-weight: 600;\n}\n\n    \n\n    \n        \n        \n            \n                Legend\n            \n            \n                Html element\n            \n            \n                Component\n            \n            \n                Html element with directive\n            \n        \n    \n\n    \n\n\n\n\n\n\n        var COMPONENT_TEMPLATE = '              {{notification.content}}      -->          '\n    var COMPONENTS = [{'name': 'AboutComponent', 'selector': 'app-about'},{'name': 'AccountMappingComponent', 'selector': 'app-account-mapping'},{'name': 'AccountPanelComponent', 'selector': 'app-account-panel'},{'name': 'AccountSettingsComponent', 'selecto