    "injectables/NotificationsService.html": {
      url: "injectables/NotificationsService.html",
      title: "injectable - NotificationsService",
      body: "\n                   \n\n\n\n\n\n\n\n\n  Injectables\n  NotificationsService\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n\n\n\n    \n        \n            File\n        \n        \n            src/services/classes/notifications/notifications.service.ts\n        \n\n\n\n\n\n            \n    Index\n    \n        \n                \n                    \n                        Properties\n                    \n                \n                \n                    \n                        \n                            \n                                alertStatus\n                            \n                            \n                                message\n                            \n                            \n                                notification\n                            \n                        \n                    \n                \n\n                \n                    \n                        Methods\n                    \n                \n                \n                    \n                        \n                            \n                                dismissMessage\n                            \n                            \n                                publishMessages\n                            \n                        \n                    \n                \n\n\n\n\n\n        \n    \n\n\n            \n    Constructor\n        \n            \n                \n                    \nconstructor()\n                    \n                \n                        \n                            \n                                Defined in src/services/classes/notifications/notifications.service.ts:9\n                            \n                        \n\n            \n        \n\n\n            \n    \n    \n        Methods\n    \n    \n        \n            \n                \n                    \n                    \n                        dismissMessage\n                        \n                    \n                \n            \n            \n                \ndismissMessage()\n                \n            \n\n\n            \n                \n                    Defined in src/services/classes/notifications/notifications.service.ts:22\n                \n            \n\n\n            \n                \n\n                    \n                        Returns :         void\n\n                    \n                \n            \n        \n    \n    \n        \n            \n                \n                    \n                    \n                        publishMessages\n                        \n                    \n                \n            \n            \n                \npublishMessages(content: string, style: string, type: number)\n                \n            \n\n\n            \n                \n                    Defined in src/services/classes/notifications/notifications.service.ts:15\n                \n            \n\n\n            \n                \n\n                    \n                        Parameters :\n                        \n                        \n                            \n                                \n                                    Name\n                                    Type\n                                    Optional\n                                \n                            \n                            \n                                \n                                    content\n                                    \n                                                string\n                                    \n\n                                    \n                                        No\n                                    \n\n\n                                \n                                \n                                    style\n                                    \n                                                string\n                                    \n\n                                    \n                                        No\n                                    \n\n\n                                \n                                \n                                    type\n                                    \n                                                number\n                                    \n\n                                    \n                                        No\n                                    \n\n\n                                \n                            \n                        \n                    \n                    \n                    \n                    \n                        Returns :         void\n\n                    \n                    \n                        \n                    \n                \n            \n        \n    \n\n            \n    \n    \n        Properties\n    \n    \n        \n            \n                \n                    \n                    \n                        alertStatus\n                        \n                    \n                \n            \n                \n                    \n                        Type :     BehaviorSubject\n\n                    \n                \n                \n                    \n                        Default value : new BehaviorSubject({content:'testing', style:'info', type:0, show:false})\n                    \n                \n                    \n                        \n                                Defined in src/services/classes/notifications/notifications.service.ts:13\n                        \n                    \n\n\n        \n    \n    \n        \n            \n                \n                    \n                    \n                        message\n                        \n                    \n                \n            \n                \n                    \n                        Type :         string\n\n                    \n                \n                    \n                        \n                                Defined in src/services/classes/notifications/notifications.service.ts:8\n                        \n                    \n\n\n        \n    \n    \n        \n            \n                \n                    \n                    \n                        notification\n                        \n                    \n                \n            \n                \n                    \n                        Type :     EventEmitter\n\n                    \n                \n                \n                    \n                        Default value : new EventEmitter()\n                    \n                \n                    \n                        \n                                Defined in src/services/classes/notifications/notifications.service.ts:9\n                        \n                    \n\n\n        \n    \n\n\n    \n\n\n    \n        import { Injectable, EventEmitter } from '@angular/core';\nimport { BehaviorSubject } from 'rxjs';\nimport {  } from 'events';\n@Injectable({\n  providedIn: 'root'\n})\nexport class NotificationsService {\n  message:string;\n  notification:EventEmitter = new EventEmitter()\n  constructor() { }\n\n\n  alertStatus: BehaviorSubject = new BehaviorSubject({content:'testing', style:'info', type:0, show:false})\n\n  publishMessages(content: string, style: string, type:number) {\n    this.alertStatus.next({ content: content, style: style, type: 0, show: true });\n    setTimeout(() => {\n      this.dismissMessage()\n    }, 10000);\n  }\n\n  dismissMessage() {\n    this.alertStatus.next({ content: '', style: 'info', type: 0, show: false });\n  }\n\n}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
    },
