      title: "module - ParentPortalModule",
      body: "\n                   \n\n\n\n\n    Modules\n    ParentPortalModule\n\n\n\n    \n        \n\n\n\n\n\ndependencies\n\ndependencies\n\ncluster_ParentPortalModule\n\n\n\ncluster_ParentPortalModule_imports\n\n\n\ncluster_ParentPortalModule_declarations\n\n\n\n\nBillingComponent\n\nBillingComponent\n\n\n\nParentPortalModule\n\nParentPortalModule\n\nParentPortalModule -->\n\nBillingComponent->ParentPortalModule\n\n\n\n\n\nChildAssignmentComponent\n\nChildAssignmentComponent\n\nParentPortalModule -->\n\nChildAssignmentComponent->ParentPortalModule\n\n\n\n\n\nChildAttendanceComponent\n\nChildAttendanceComponent\n\nParentPortalModule -->\n\nChildAttendanceComponent->ParentPortalModule\n\n\n\n\n\nLandingScreenComponent\n\nLandingScreenComponent\n\nParentPortalModule -->\n\nLandingScreenComponent->ParentPortalModule\n\n\n\n\n\nParentPortalComponent\n\nParentPortalComponent\n\nParentPortalModule -->\n\nParentPortalComponent->ParentPortalModule\n\n\n\n\n\nReportCardComponent\n\nReportCardComponent\n\nParentPortalModule -->\n\nReportCardComponent->ParentPortalModule\n\n\n\n\n\nViewAssignmentComponent\n\nViewAssignmentComponent\n\nParentPortalModule -->\n\nViewAssignmentComponent->ParentPortalModule\n\n\n\n\n\nViewBillingComponent\n\nViewBillingComponent\n\nParentPortalModule -->\n\nViewBillingComponent->ParentPortalModule\n\n\n\n\n\nViewReportCardComponent\n\nViewReportCardComponent\n\nParentPortalModule -->\n\nViewReportCardComponent->ParentPortalModule\n\n\n\n\n\nViewReportSheetComponent\n\nViewReportSheetComponent\n\nParentPortalModule -->\n\nViewReportSheetComponent->ParentPortalModule\n\n\n\n\n\nParentPortalRoutingModule\n\nParentPortalRoutingModule\n\nParentPortalModule -->\n\nParentPortalRoutingModule->ParentPortalModule\n\n\n\n\n\nSharedModule\n\nSharedModule\n\nParentPortalModule -->\n\nSharedModule->ParentPortalModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/parent-portal/parent-portal.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Declarations\n                    \n                        \n                            BillingComponent\n                        \n                        \n                            ChildAssignmentComponent\n                        \n                        \n                            ChildAttendanceComponent\n                        \n                        \n                            LandingScreenComponent\n                        \n                        \n                            ParentPortalComponent\n                        \n                        \n                            ReportCardComponent\n                        \n                        \n                            ViewAssignmentComponent\n                        \n                        \n                            ViewBillingComponent\n                        \n                        \n                            ViewReportCardComponent\n                        \n                        \n                            ViewReportSheetComponent\n                        \n                    \n                \n                \n                    Imports\n                    \n                        \n                            ParentPortalRoutingModule\n                        \n                        \n                            SharedModule\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { CommonModule } from '@angular/common';\n\nimport { ParentPortalRoutingModule } from './parent-portal-routing.module';\nimport { ParentPortalComponent } from './parent-portal.component';\nimport { LandingScreenComponent } from './landing-screen/landing-screen.component';\nimport { DashboardComponent } from './dashboard/dashboard.component';\nimport { ChildAssignmentComponent } from './child-assignment/child-assignment.component';\nimport { TimeTableComponent } from './time-table/time-table.component';\nimport { BillingComponent } from './billing/billing.component';\nimport { ViewAssignmentComponent } from './view-assignment/view-assignment.component';\nimport { ReportCardComponent } from './report-card/report-card.component';\nimport { ChildAttendanceComponent } from './child-attendance/child-attendance.component';\nimport { ViewBillingComponent } from './view-billing/view-billing.component';\nimport { ViewReportCardComponent } from './view-report-card/view-report-card.component';\nimport { SharedModule } from '../shared/shared.module';\nimport { ViewReportSheetComponent } from './view-report-sheet/view-report-sheet.component';\nimport { FormsModule, ReactiveFormsModule } from '@angular/forms';\n\n\n@NgModule({\n  declarations: [\n    ParentPortalComponent,\n    LandingScreenComponent,\n    DashboardComponent,\n    ChildAssignmentComponent,\n    TimeTableComponent,\n    BillingComponent,\n    ViewAssignmentComponent,\n    ReportCardComponent,\n    ChildAttendanceComponent,\n    ViewBillingComponent,\n    ViewReportCardComponent,\n    ViewReportSheetComponent],\n  imports: [\n    CommonModule,\n    ReactiveFormsModule,\n    FormsModule,\n    SharedModule,\n    ParentPortalRoutingModule\n  ]\n})\nexport class ParentPortalModule { }\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
