      url: "modules/SharedModule.html",
      title: "module - SharedModule",
      body: "\n                   \n\n\n\n\n    Modules\n    SharedModule\n\n\n\n    \n        \n\n\n\n\n\ndependencies\n\ndependencies\n\ncluster_SharedModule\n\n\n\ncluster_SharedModule_exports\n\n\n\ncluster_SharedModule_declarations\n\n\n\n\nFooterComponent\n\nFooterComponent\n\n\n\nSharedModule\n\nSharedModule\n\nSharedModule -->\n\nFooterComponent->SharedModule\n\n\n\n\n\nHomenavbarComponent\n\nHomenavbarComponent\n\nSharedModule -->\n\nHomenavbarComponent->SharedModule\n\n\n\n\n\nLoaderComponent\n\nLoaderComponent\n\nSharedModule -->\n\nLoaderComponent->SharedModule\n\n\n\n\n\nNoRecordComponent\n\nNoRecordComponent\n\nSharedModule -->\n\nNoRecordComponent->SharedModule\n\n\n\n\n\nNotificationsComponent\n\nNotificationsComponent\n\nSharedModule -->\n\nNotificationsComponent->SharedModule\n\n\n\n\n\nTableSearchPipe\n\nTableSearchPipe\n\nSharedModule -->\n\nTableSearchPipe->SharedModule\n\n\n\n\n\nTrustedHtmlPipe\n\nTrustedHtmlPipe\n\nSharedModule -->\n\nTrustedHtmlPipe->SharedModule\n\n\n\n\n\nTrustedUrlPipe\n\nTrustedUrlPipe\n\nSharedModule -->\n\nTrustedUrlPipe->SharedModule\n\n\n\n\n\nFooterComponent \n\nFooterComponent \n\nFooterComponent  -->\n\nSharedModule->FooterComponent \n\n\n\n\n\nHomenavbarComponent \n\nHomenavbarComponent \n\nHomenavbarComponent  -->\n\nSharedModule->HomenavbarComponent \n\n\n\n\n\nLoaderComponent \n\nLoaderComponent \n\nLoaderComponent  -->\n\nSharedModule->LoaderComponent \n\n\n\n\n\nNoRecordComponent \n\nNoRecordComponent \n\nNoRecordComponent  -->\n\nSharedModule->NoRecordComponent \n\n\n\n\n\nNotificationsComponent \n\nNotificationsComponent \n\nNotificationsComponent  -->\n\nSharedModule->NotificationsComponent \n\n\n\n\n\nTableSearchPipe \n\nTableSearchPipe \n\nTableSearchPipe  -->\n\nSharedModule->TableSearchPipe \n\n\n\n\n\nTrustedHtmlPipe \n\nTrustedHtmlPipe \n\nTrustedHtmlPipe  -->\n\nSharedModule->TrustedHtmlPipe \n\n\n\n\n\nTrustedUrlPipe \n\nTrustedUrlPipe \n\nTrustedUrlPipe  -->\n\nSharedModule->TrustedUrlPipe \n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/shared/shared.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Declarations\n                    \n                        \n                            FooterComponent\n                        \n                        \n                            HomenavbarComponent\n                        \n                        \n                            LoaderComponent\n                        \n                        \n                            NoRecordComponent\n                        \n                        \n                            NotificationsComponent\n                        \n                        \n                            TableSearchPipe\n                        \n                        \n                            TrustedHtmlPipe\n                        \n                        \n                            TrustedUrlPipe\n                        \n                    \n                \n                \n                    Exports\n                    \n                        \n                            FooterComponent\n                        \n                        \n                            HomenavbarComponent\n                        \n                        \n                            LoaderComponent\n                        \n                        \n                            NoRecordComponent\n                        \n                        \n                            NotificationsComponent\n                        \n                        \n                            TableSearchPipe\n                        \n                        \n                            TrustedHtmlPipe\n                        \n                        \n                            TrustedUrlPipe\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { CommonModule } from '@angular/common';\nimport { RouterModule } from '@angular/router';\nimport { HomenavbarComponent } from './homenavbar/homenavbar.component';\nimport { FooterComponent } from './footer/footer.component';\nimport { LoaderComponent } from './loader/loader.component';\nimport { NotificationsComponent } from './notifications/notifications.component';\nimport { TableSearchPipe } from './pipes/table-search.pipe';\nimport { TrustedUrlPipe } from './pipes/trusted-url.pipe';\nimport { NoRecordComponent } from './no-record/no-record.component';\nimport { TrustedHtmlPipe } from './pipes/trusted-html.pipe';\n\n\n\n@NgModule({\n  declarations: [\n    HomenavbarComponent,\n    FooterComponent,\n    LoaderComponent,\n    NotificationsComponent,\n    TableSearchPipe,\n    TrustedUrlPipe,\n    NoRecordComponent,\n    TrustedHtmlPipe\n  ],\n  imports: [\n    CommonModule,\n    RouterModule\n  ],\n  exports: [\n    HomenavbarComponent,\n    FooterComponent,\n    NotificationsComponent,\n    NoRecordComponent,\n    LoaderComponent,\n    TableSearchPipe,\n    TrustedUrlPipe,\n    TrustedHtmlPipe\n  ]\n})\nexport class SharedModule { }\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
